"use client";

import * as React from "react";
import { cn } from "../../lib/utils";
import { ChevronRight, House } from "./icons";

// Breadcrumb: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface BreadcrumbItem {
  label: React.ReactNode;
  href?: string;
}

export interface BreadcrumbProps extends React.HTMLAttributes<HTMLElement> {
  items: BreadcrumbItem[];
  separator?: "chevron" | "slash";
  /** Home icon before the first item. */
  showHome?: boolean;
}

const Breadcrumb = React.forwardRef<HTMLElement, BreadcrumbProps>(
  ({ className, items, separator = "chevron", showHome = false, ...props }, ref) => (
    <nav ref={ref} data-slot="breadcrumb" data-kind="control" aria-label="Breadcrumb" className={cn("skin-quiet", className)} {...props}>
      <ol className="flex flex-wrap items-center gap-2">
        {showHome ? (
          <li className="flex items-center">
            <House aria-hidden className="size-4 text-icon-secondary" />
          </li>
        ) : null}
        {items.map((item, index) => {
          const last = index === items.length - 1;
          return (
            <li key={index} className="flex items-center gap-2">
              {showHome || index > 0 ? (
                separator === "slash" ? (
                  <span aria-hidden className="text-body-small text-fg-tertiary">
                    /
                  </span>
                ) : (
                  <ChevronRight aria-hidden className="size-4 text-fg-tertiary" />
                )
              ) : null}
              {last || !item.href ? (
                <span aria-current={last ? "page" : void 0} className={last ? "text-label-medium text-fg-primary" : "text-body-small text-fg-secondary"}>
                  {item.label}
                </span>
              ) : (
                <a href={item.href} className="text-body-small text-fg-secondary rounded-xs hover:underline underline-offset-4 hover:text-fg-primary focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
                  {item.label}
                </a>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  ),
);
Breadcrumb.displayName = "Breadcrumb";

export { Breadcrumb };
